SELECT DISTINCTROW Имена_станций.NAME, STAN.Year, STAN.OBL, IIf(STAN.gaz>0,z(STOIM.gaz)/z(STAN.gaz),0) AS GAZ_c, IIf(DUG.gazpp>0,z(STOIM.gazpp)/z(DUG.gazpp),0) AS gazpp_c, IIf(DUG.gaz_prir>0,z(STOIM.gaz_prir)/z(DUG.gaz_prir),0) AS gaz_prir_c, IIf(STAN.mazut>0,z(STOIM.mazut)/z(STAN.mazut),0) AS MAZUT_c, IIf(DUG.disel>0,z(STOIM.disel)/z(DUG.disel),0) AS disel_c, IIf(DUG.maztop>0,z(STOIM.maztop)/z(DUG.maztop),0) AS maztop_c, IIf(DUG.gtt>0,z(STOIM.gtt)/z(DUG.gtt),0) AS gtt_c, IIf(DUG.nft_proch>0,z(STOIM.nft_proch)/z(DUG.nft_proch),0) AS nft_proch_c, IIf(STAN.torf>0,z(STOIM.torf)/z(STAN.torf),0) AS TORF_c, IIf(STAN.ISK_GAZ>0,z(STOIM.isk_gaz)/z(STAN.isk_gaz),0) AS ISK_GAZ_c, IIf(DUG.domen_g>0,z(STOIM.domen_g)/z(DUG.domen_g),0) AS domen_g_c, IIf(DUG.koks_g>0,z(STOIM.koks_g)/z(DUG.koks_g),0) AS koks_g_c, IIf(DUG.prochgaz>0,z(STOIM.prochgaz)/z(DUG.prochgaz),0) AS prochgaz_c, IIf(STAN.proch>0,z(STOIM.proch)/z(STAN.proch),0) AS PROCH_c, IIf(DUG.tvproch>0,z(STOIM.tvproch)/z(DUG.tvproch),0) AS tvproch_c, IIf(DUG.szh_gaz>0,z(STOIM.szh_gaz)/z(DUG.szh_gaz),0) AS szh_gaz_c, IIf(DUG.inoe>0,z(STOIM.inoe)/z(DUG.inoe),0) AS inoe_c, IIf(STAN.don>0,z(STOIM.don)/z(STAN.don),0) AS DON_c, IIf(STAN.podm>0,z(STOIM.podm)/z(STAN.podm),0) AS PODM_c, IIf(STAN.pech>0,z(STOIM.pech)/z(STAN.pech),0) AS PECH_c, IIf(DUG.vork>0,z(STOIM.vork)/z(DUG.vork),0) AS vork_c, IIf(DUG.intin>0,z(STOIM.intin)/z(DUG.intin),0) AS intin_c, IIf(STAN.kuzn>0,z(STOIM.kuzn)/z(STAN.kuzn),0) AS KUZN_c, IIf(DUG.kuzngd>0,z(STOIM.kuzngd)/z(DUG.kuzngd),0) AS kuzngd_c, IIf(DUG.kuznt>0,z(STOIM.kuznt)/z(DUG.kuznt),0) AS kuznt_c, IIf(DUG.kuznss>0,z(STOIM.kuznss)/z(DUG.kuznss),0) AS kuznss_c, IIf(DUG.kuznun>0,z(STOIM.kuznun)/z(DUG.kuznun),0) AS kuznun_c, IIf(STAN.ural>0,z(STOIM.ural)/z(STAN.ural),0) AS URAL_c, IIf(DUG.sver>0,z(STOIM.sver)/z(DUG.sver),0) AS sver_c, IIf(DUG.chel>0,z(STOIM.chel)/z(DUG.chel),0) AS chel_c, IIf(DUG.kizel>0,z(STOIM.kizel)/z(DUG.kizel),0) AS kizel_c, IIf(STAN.bashk>0,z(STOIM.bashk)/z(STAN.bashk),0) AS BASHK_c, IIf(STAN.kazah>0,z(STOIM.kazah)/z(STAN.kazah),0) AS KAZAH_c, IIf(DUG.ekib>0,z(STOIM.ekib)/z(DUG.ekib),0) AS ekib_c, IIf(DUG.maikub>0,z(STOIM.maikub)/z(DUG.maikub),0) AS maikub_c, IIf(DUG.karag>0,z(STOIM.karag)/z(DUG.karag),0) AS karag_c, IIf(DUG.karajyra>0,z(STOIM.karajyra)/z(DUG.karajyra),0) AS karajyra_c, IIf(DUG.teniz>0,z(STOIM.teniz)/z(DUG.teniz),0) AS teniz_c, IIf(STAN.kan>0,z(STOIM.kan)/z(STAN.kan),0) AS KAN_c, IIf(DUG.nazar>0,z(STOIM.nazar)/z(DUG.nazar),0) AS nazar_c, IIf(DUG.ibor>0,z(STOIM.ibor)/z(DUG.ibor),0) AS ibor_c, IIf(DUG.berez>0,z(STOIM.berez)/z(DUG.berez),0) AS berez_c, IIf(DUG.per>0,z(STOIM.per)/z(DUG.per),0) AS per_c, IIf(DUG.irbei>0,z(STOIM.irbei)/z(DUG.irbei),0) AS irbei_c, IIf(DUG.kansk>0,z(STOIM.kansk)/z(DUG.kansk),0) AS kansk_c, IIf(STAN.irkut>0,z(STOIM.irkut)/z(STAN.irkut),0) AS IRKUT_c, IIf(DUG.azey>0,z(STOIM.azey)/z(DUG.azey),0) AS azey_c, IIf(DUG.mug>0,z(STOIM.mug)/z(DUG.mug),0) AS mug_c, IIf(DUG.cher>0,z(STOIM.cher)/z(DUG.cher),0) AS cher_c, IIf(STAN.tung>0,z(STOIM.tung)/z(STAN.tung),0) AS TUNG_c, IIf(DUG.jer>0,z(STOIM.jer)/z(DUG.jer),0) AS jer_c, IIf(DUG.karab>0,z(STOIM.karab)/z(DUG.karab),0) AS karab_c, IIf(STAN.hak>0,z(STOIM.hak)/z(STAN.hak),0) AS HAK_c, IIf(STAN.tuv>0,z(STOIM.tuv)/z(STAN.tuv),0) AS TUV_c, IIf(STAN.bur>0,z(STOIM.bur)/z(STAN.bur),0) AS BUR_c, IIf(DUG.gusin>0,z(STOIM.gusin)/z(DUG.gusin),0) AS gusin_c, IIf(DUG.tugn>0,z(STOIM.tugn)/z(DUG.tugn),0) AS tugn_c, IIf(DUG.okino>0,z(STOIM.okino)/z(DUG.okino),0) AS okino_c, IIf(STAN.chit>0,z(STOIM.chit)/z(STAN.chit),0) AS CHIT_c, IIf(DUG.har>0,z(STOIM.har)/z(DUG.har),0) AS har_c, IIf(DUG.urt>0,z(STOIM.urt)/z(DUG.urt),0) AS urt_c, IIf(DUG.tataur>0,z(STOIM.tataur)/z(DUG.tataur),0) AS tataur_c, IIf(DUG.tarbag>0,z(STOIM.tarbag)/z(DUG.tarbag),0) AS tarbag_c, IIf(DUG.zab_kam>0,z(STOIM.zab_kam)/z(DUG.zab_kam),0) AS zab_kam_c, IIf(STAN.amur>0,z(STOIM.amur)/z(STAN.amur),0) AS AMUR_c, IIf(DUG.rai>0,z(STOIM.rai)/z(DUG.rai),0) AS rai_c, IIf(DUG.erk>0,z(STOIM.erk)/z(DUG.erk),0) AS erk_c, IIf(DUG.ogodj>0,z(STOIM.ogodj)/z(DUG.ogodj),0) AS ogodj_c, IIf(DUG.svo>0,z(STOIM.svo)/z(DUG.svo),0) AS svo_c, IIf(STAN.urg>0,z(STOIM.urg)/z(STAN.urg),0) AS URG_c, IIf(STAN.ushum>0,z(STOIM.ushum)/z(STAN.ushum),0) AS USHUM_c, IIf(STAN.prim>0,z(STOIM.prim)/z(STAN.prim),0) AS PRIM_c, IIf(DUG.bikin>0,z(STOIM.bikin)/z(DUG.bikin),0) AS bikin_c, IIf(DUG.razdol>0,z(STOIM.razdol)/z(DUG.razdol),0) AS razdol_c, IIf(DUG.hankai>0,z(STOIM.hankai)/z(DUG.hankai),0) AS hankai_c, IIf(STAN.yakut>0,z(STOIM.yakut)/z(STAN.yakut),0) AS YAKUT_c, IIf(DUG.neru>0,z(STOIM.neru)/z(DUG.neru),0) AS neru_c, IIf(DUG.zyryan>0,z(STOIM.zyryan)/z(DUG.zyryan),0) AS zyryan_c, IIf(DUG.pyak>0,z(STOIM.pyak)/z(DUG.pyak),0) AS pyak_c, IIf(STAN.mag>0,z(STOIM.mag)/z(STAN.mag),0) AS MAG_c, IIf(STAN.chukot>0,z(STOIM.chukot)/z(STAN.chukot),0) AS CHUKOT_c, IIf(DUG.anad>0,z(STOIM.anad)/z(DUG.anad),0) AS anad_c, IIf(DUG.bering>0,z(STOIM.bering)/z(DUG.bering),0) AS bering_c, IIf(STAN.kamch>0,z(STOIM.kamch)/z(STAN.kamch),0) AS KAMCH_c, IIf(STAN.sah>0,z(STOIM.sah)/z(STAN.sah),0) AS SAH_c, STAN.NUMB1120, IIf(STAN.ved>0,0,1) AS sost, IIf(main>0,1,0) AS [group] INTO Цена2024
FROM ((Станции2024 AS STAN LEFT JOIN Доп_угли2024 AS DUG ON STAN.NUMB1120 = DUG.NUMB1120) LEFT JOIN Стоимость2024 AS STOIM ON STAN.NUMB1120 = STOIM.NUMB1120) INNER JOIN Имена_станций ON STAN.NUMB1120 = Имена_станций.NUMB
WHERE IIf(main>0,1,0)=0
ORDER BY STAN.numb1;
